// Stage 2: Heuristic Scoring & Archetype Fingerprinting
const rows = $input.all().map(i => i.json);
if (!rows || rows.length === 0) {
  return [];
}

const jobId = $('Webhook: Ingestion Complete').first().json.body.job_id;

// 1. Group candidate loan products by user_id
const usersMap = {};
for (const row of rows) {
  if (!usersMap[row.user_id]) {
    usersMap[row.user_id] = {
      user_db_id: row.user_db_id,
      user_id: row.user_id,
      email: row.email,
      monthly_income: parseFloat(row.monthly_income),
      credit_score: parseInt(row.credit_score, 10),
      employment_status: row.employment_status,
      age: parseInt(row.age, 10),
      candidates: []
    };
  }

  // Calculate heuristic match score (0-100)
  // Weighted on: APR competitiveness (40%), Income headroom (35%), Score buffer (25%)
  const rateScore = Math.max(0, 40 * (1 - ((parseFloat(row.interest_rate) - 9.0) / 10.0)));
  const incomeRatio = Math.min(2.0, parseFloat(row.monthly_income) / (parseFloat(row.min_monthly_income) || 25000));
  const incomeScore = 35 * (incomeRatio / 2.0);
  const scoreHeadroom = Math.min(1.0, (parseInt(row.credit_score, 10) - parseInt(row.min_credit_score, 10)) / 150.0);
  const scorePoints = 25 * Math.max(0, scoreHeadroom);

  const totalScore = Math.min(99.0, Math.max(50.0, rateScore + incomeScore + scorePoints));

  usersMap[row.user_id].candidates.push({
    product_db_id: row.product_db_id,
    provider_name: row.provider_name,
    product_name: row.product_name,
    interest_rate: parseFloat(row.interest_rate),
    match_score: parseFloat(totalScore.toFixed(2))
  });
}

// 2. Select Top-2 products and generate Archetype Fingerprint
const enrichedUsers = [];
const uniqueArchetypes = {};

for (const userId in usersMap) {
  const u = usersMap[userId];
  // Sort by match score descending
  u.candidates.sort((a, b) => b.match_score - a.match_score);
  const topOffers = u.candidates.slice(0, 2);

  // Archetype fingerprinting
  const creditTier = u.credit_score >= 750 ? 'PRIME' : (u.credit_score >= 675 ? 'NEAR_PRIME' : 'FAIR');
  const incomeBracket = u.monthly_income >= 75000 ? 'HIGH' : (u.monthly_income >= 40000 ? 'MID' : 'ENTRY');
  const empType = u.employment_status.toLowerCase();
  const prodKey = topOffers.map(o => o.provider_name.replace(/\s+/g, '')).sort().join('_');
  const archetypeKey = `${creditTier}_${empType}_${incomeBracket}_${prodKey}`;

  if (!uniqueArchetypes[archetypeKey]) {
    uniqueArchetypes[archetypeKey] = {
      archetype_key: archetypeKey,
      credit_tier: creditTier,
      employment_type: empType,
      income_bracket: incomeBracket,
      matched_products: topOffers.map(o => `${o.provider_name} ${o.product_name}`).join(', '),
      sample_top_rate: topOffers[0].interest_rate
    };
  }

  enrichedUsers.push({
    user_db_id: u.user_db_id,
    user_id: u.user_id,
    email: u.email,
    credit_score: u.credit_score,
    monthly_income: u.monthly_income,
    archetype_key: archetypeKey,
    top_offers: topOffers
  });
}

return [{
  json: {
    job_id: jobId,
    enriched_users: enrichedUsers,
    archetypes_in_batch: Object.values(uniqueArchetypes)
  }
}];

// Identify cache misses vs cache hits
const stage2Data = $('Stage 2: Heuristics & Fingerprinting').first().json;
const cachedRows = $input.all().map(i => i.json);

const cacheMap = {};
for (const r of cachedRows) {
  cacheMap[r.archetype_key] = r.rationale_template;
}

const neededArchetypes = stage2Data.archetypes_in_batch;
const misses = neededArchetypes.filter(a => !cacheMap[a.archetype_key]);

return [{
  json: {
    job_id: stage2Data.job_id,
    enriched_users: stage2Data.enriched_users,
    cache_map: cacheMap,
    cache_misses: misses,
    has_misses: misses.length > 0
  }
}];

// Hydrate personalized user reasons and build flat matches for DB insert
const input = $input.first().json;
const users = input.enriched_users;
const cacheMap = input.cache_map;
const jobId = input.job_id;

const flatMatches = [];

for (const user of users) {
  const template = cacheMap[user.archetype_key] || 
    'Hi {{user_name}}, based on your financial profile, you qualify for {{matched_products}} with pre-approved interest rates starting at {{top_rate}}% p.a.';

  for (const offer of user.top_offers) {
    const personalizedReason = template
      .replace(/{{user_name}}/g, user.user_id)
      .replace(/{{top_rate}}/g, offer.interest_rate.toString())
      .replace(/{{matched_products}}/g, offer.product_name);

    flatMatches.push({
      job_id: jobId,
      user_db_id: user.user_db_id,
      product_db_id: offer.product_db_id,
      match_score: offer.match_score,
      archetype_key: user.archetype_key,
      eligibility_reason: personalizedReason
    });
  }
}

return flatMatches.map(m => ({ json: m }));
